// a is sorted ascending
int Search(int[] a, int target) {
    int lo = 0, hi = a.Length - 1;          // candidates are a[lo..hi]
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;       // middle without overflow
        if (a[mid] == target) return mid;
        if (a[mid] < target) lo = mid + 1;  // the left half is out
        else hi = mid - 1;                  // the right half is out
    }
    return -1;
}

