int LowerBound(int[] a, int x) {
    int lo = 0, hi = a.Length;           // hi is not included
    while (lo < hi) {                    // empty when lo == hi
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < x) lo = mid + 1;    // a[mid] is too small — not the answer
        else hi = mid;                   // a[mid] fits — the answer is not to its right
