public sealed class IntDeque {
    int[] buf = new int[16];              // capacity is a power of two
    int head, count;                      // head is the index of the first element

    public int Count => count;
    public int Front => buf[head];
    public int Back => buf[(head + count - 1) & (buf.Length - 1)];

    public void PushBack(int x) {
        if (count == buf.Length) Grow();
        buf[(head + count) & (buf.Length - 1)] = x;
        count++;
    }
    public void PushFront(int x) {
        if (count == buf.Length) Grow();
        head = (head - 1) & (buf.Length - 1);   // -1 & mask = mask: one step back around the ring
        buf[head] = x;
        count++;
    }
    public void PopBack() => count--;
    public void PopFront() { head = (head + 1) & (buf.Length - 1); count--; }

    void Grow() {                         // lay the elements out in order in an array twice as big
        var nb = new int[buf.Length * 2];
        for (int i = 0; i < count; i++) nb[i] = buf[(head + i) & (buf.Length - 1)];
        buf = nb; head = 0;
    }
}

// #1438: the longest subarray where max - min <= limit (IntDeque is from the previous card)
var maxD = new IntDeque(); var minD = new IntDeque();   // indices
int l = 0, best = 0;
for (int r = 0; r < nums.Length; r++) {
    while (maxD.Count > 0 && nums[maxD.Back] <= nums[r]) maxD.PopBack();
    while (minD.Count > 0 && nums[minD.Back] >= nums[r]) minD.PopBack();
    maxD.PushBack(r); minD.PushBack(r);
    while (nums[maxD.Front] - nums[minD.Front] > limit) {   // bad window: shrink
        l++;
        if (maxD.Front < l) maxD.PopFront();
        if (minD.Front < l) minD.PopFront();
    }
    best = Math.Max(best, r - l + 1);
}

